@Component("claim-handler")
@ProcessingGroup("claim-processing-group")
public class ClaimEventHandler {
	
	// core constructor
	ClaimEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateClaimEvent
     */
    @EventHandler
    public void handle( CreateClaimEvent event) {
        entityManager.persist(new Claim(event.getClaimId(), event.getClaimNumber(), event.getTotalAmount(), event.getPatient(), event.getCoverage(), event.getEncounter(), event.getInvoices(), event.getPayer(), event.getStatus()));
    }

    /*
     * @param	event UpdateClaimEvent
     */
    @EventHandler
    public Claim handle( UpdateClaimEvent event) {
    	entityManager.merge(new Claim(event.getClaimId(), event.getClaimNumber(), event.getTotalAmount(), event.getPatient(), event.getCoverage(), event.getEncounter(), event.getInvoices(), event.getPayer(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteClaimEvent
     */
    @EventHandler
    public void on( DeleteClaimEvent event) {
    	Claim entity = new Claim();
   
    	// ------------------------------------------
    	// apply the ClaimId
    	// ------------------------------------------
    	entity.setClaimId( event.getClaimId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ClaimRepository claimEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ClaimEventHandler.class.getName());

}
